/**
 * Durable built-in evidence corpus for the Apple Support AI agent.
 *
 * The full ML path (FAISS index over 105,871 pairs extracted from the real
 * twcs.csv dataset) lives in hiver-support-agent/models/ — heavy artifacts
 * that are occasionally rebuilt from source and can be unavailable (cold
 * sandbox, rebuild in progress). This curated corpus is the ALWAYS-AVAILABLE
 * fallback: it ships as source code with the service, loads in ~1 ms and
 * needs zero native dependencies.
 *
 * Style notes (kept faithful to the 2017 AppleSupport support voice seen in
 * the twcs dataset): short customer tweets, warm concise replies, generic
 * troubleshooting steps that were standard guidance at the time, DM invites
 * whenever private details are involved. No invented prices, dates, policies
 * or links — every concrete step (force-restart button sequence, settings
 * paths, iforgot.apple.com) is real, verifiable guidance that appears in the
 * historical support replies.
 *
 * Every taxonomy intent from Phase 2 (src/intents/taxonomy.py) is covered so
 * lexical retrieval always has on-topic evidence to ground a reply.
 */

export interface BuiltinPair {
  id: string;
  conversation_id: string;
  turn: number;
  customer_message: string;
  support_response: string;
  predicted_intent: string;
  predicted_confidence: number;
}

